#!/usr/bin/env python3
from __future__ import annotations
import argparse, base64, zlib
from pathlib import Path

class PatchError(RuntimeError): pass

def dec(s: str) -> str: return zlib.decompress(base64.b64decode(s)).decode('utf-8')
HOME_B64 = ""
CSS_B64 = ""
JS_B64 = ""

def once(text, old, new, label):
    n=text.count(old)
    if n!=1: raise PatchError(f"{label}: expected exactly 1 match, found {n}")
    return text.replace(old,new,1)

def region(text,start,end,new,label):
    a=text.find(start); b=text.find(end,a+1) if a>=0 else -1
    if a<0 or b<0: raise PatchError(f"{label}: anchors not found")
    return text[:a]+new.rstrip()+"\n\n"+text[b:]

def apply(repo: Path):
    p=repo/'include'/'web_pages.h'; t=p.read_text()
    t=region(t,'<!-- ===== Smart Home RC3 browser command center ===== -->','<!-- ===== Workshop workspace ===== -->',dec(HOME_B64),'workshop-first Home')
    p.write_text(t)
    p=repo/'web'/'app.css'; t=p.read_text(); marker='/* Smart Home v10.4.1 workshop-first Home */'
    if marker not in t: t += dec(CSS_B64)
    p.write_text(t)
    p=repo/'web'/'app.js'; t=p.read_text()
    if marker not in t: t += dec(JS_B64)
    p.write_text(t)
    p=repo/'include'/'smart_home_build.h'; t=p.read_text()
    t=once(t,'#define SMART_HOME_VERSION "v10.4"','#define SMART_HOME_VERSION "v10.4.1"','version')
    t=once(t,'Smart Home v10.4 Portal UX RC1','Smart Home v10.4.1 Workshop Home Hub RC2','build label')
    p.write_text(t)
    verify(repo)

def verify(repo: Path):
    pages=(repo/'include'/'web_pages.h').read_text(); app=(repo/'web'/'app.js').read_text(); css=(repo/'web'/'app.css').read_text(); build=(repo/'include'/'smart_home_build.h').read_text()
    a=pages.index('id="sec-home"'); b=pages.index('id="sec-workshop"'); home=pages[a:b]
    for n in ['Your workshop at a glance.','data-hh-widget="workshop"','data-hh-widget="printer"','data-hh-widget="device"','data-hh-widget="network"','data-hh-widget="system"','data-hh-widget="quick"','Deep telemetry, connection settings and printer controls live on the Printer page.','Go where the work is']:
        if n not in home: raise PatchError('Home invariant missing: '+n)
    if 'class="cc-grid"' in home or 'LIVE PRINT' in home: raise PatchError('legacy printer-first Home survived')
    for n in ['function hhApplyStatus','function refreshCommandCenter(manual)','function ccRefreshLiveWidget(){}','Printer is one source, never the sole definition of Home health.',"HH_WIDGET_IDS=['workshop','printer','device','network','system','quick']"]:
        if n not in app: raise PatchError('Home JS invariant missing: '+n)
    for n in ['.hh-grid','.hh-workshop{grid-column:span 7}','.hh-printer{grid-column:span 5}','.hh-status-grid']:
        if n not in css: raise PatchError('Home CSS invariant missing: '+n)
    if '#define SMART_HOME_VERSION "v10.4.1"' not in build or 'Smart Home v10.4.1 Workshop Home Hub RC2' not in build: raise PatchError('v10.4.1 identity missing')

def main():
    ap=argparse.ArgumentParser(); ap.add_argument('--repo',default='.'); ap.add_argument('--apply',action='store_true'); args=ap.parse_args(); repo=Path(args.repo).resolve()
    if not args.apply: print('Smart Home v10.4.1 workshop-first Home patch ready. Use --apply.'); return 0
    apply(repo); print('Smart Home v10.4.1 Workshop Home Hub applied'); return 0
if __name__=='__main__': raise SystemExit(main())
